    None = 0,
    Animate = 1,    -- 动画展示
    Direct = 2,     -- 直接展示
    SweepAnimate = 3,   -- 在扫荡界面里面使用的时候播的动画
}
-- container 动画
local TaskAnimate =         "UIBattleEndLevelDailyTaskGo"
local TaskAnimateComplete = "UIBattleEndLevelDailyTaskCompleteGo"
local TaskDefault =         "UIBattleEndLevelDailyTaskGoDefault"
local TaskDefaultComplete = "UIBattleEndLevelDailyTaskCompleteGoDefault"

local TaskSweepComplete = "FightTeamEndLevel_TaskCellNode_Complete"
